import * as d3 from "d3";
import { Graph } from "../graph";
import type { DrawingState, EntityRef, NodeEntity, Point3D, WayEntity } from "./types";
import { entityKey } from "./types";
import { worldToScreen } from "./util";

type RendererOptions = {
  readonly onEntityContextMenu: (event: MouseEvent, entity: EntityRef) => void;
  readonly onEntityPointerDown: (event: PointerEvent, entity: EntityRef) => void;
  readonly onMidpointPointerDown: (
    event: PointerEvent,
    wayId: number,
    insertionIndex: number,
    point: Point3D,
  ) => void;
};

type RenderState = {
  readonly graph: Graph;
  readonly selection: EntityRef | null;
  readonly preview: {
    readonly graph: Graph;
    readonly ref: EntityRef;
  } | null;
  readonly drawing: DrawingState | null;
  readonly transientNode: { readonly id: number; readonly geom: Point3D } | null;
  readonly transform: d3.ZoomTransform;
};

type NodeVisibilityOptions = {
  readonly showLineVertices?: boolean;
};

const pathForWay = (
  graph: Graph,
  way: WayEntity,
  transform: d3.ZoomTransform,
  transientNode: RenderState["transientNode"],
) => {
  const points = way.nodeIds.flatMap((nodeId) => {
    const node = graph.node(nodeId);
    if (!node) return [];
    const geom = transientNode?.id === nodeId ? transientNode.geom : node.geom;
    return [worldToScreen(transform, geom)];
  });
  if (points.length === 0) return "";
  return `M${points.map(([x, y]) => `${x},${y}`).join("L")}${way.geometryKind === "area" ? "Z" : ""}`;
};

export const visibleNodesForSelection = (
  graph: Graph,
  selection: EntityRef | null,
  options: NodeVisibilityOptions = {},
): readonly NodeEntity[] => {
  const vertexNodeIds = new Set(graph.ways().flatMap((way) => way.nodeIds));
  const visibleVertexNodeIds = new Set<number>();

  if (options.showLineVertices) {
    for (const way of graph.ways()) {
      if (way.geometryKind !== "line") continue;
      for (const nodeId of way.nodeIds) visibleVertexNodeIds.add(nodeId);
    }
  }

  if (selection?.type === "way") {
    for (const nodeId of graph.way(selection.id)?.nodeIds ?? []) {
      visibleVertexNodeIds.add(nodeId);
    }
  } else if (selection?.type === "node") {
    for (const way of graph.parentWays(selection.id)) {
      for (const nodeId of way.nodeIds) visibleVertexNodeIds.add(nodeId);
    }
  }

  return graph
    .nodes()
    .filter((node) => !vertexNodeIds.has(node.id) || visibleVertexNodeIds.has(node.id));
};

export class EntitySvgLayer {
  readonly #root: d3.Selection<SVGSVGElement, unknown, null, undefined>;
  readonly #defs: d3.Selection<SVGDefsElement, unknown, null, undefined>;
  readonly #areas: d3.Selection<SVGGElement, unknown, null, undefined>;
  readonly #lines: d3.Selection<SVGGElement, unknown, null, undefined>;
  readonly #hitAreas: d3.Selection<SVGGElement, unknown, null, undefined>;
  readonly #nodes: d3.Selection<SVGGElement, unknown, null, undefined>;
  readonly #midpoints: d3.Selection<SVGGElement, unknown, null, undefined>;
  readonly #preview: d3.Selection<SVGGElement, unknown, null, undefined>;
  readonly #draft: d3.Selection<SVGGElement, unknown, null, undefined>;
  readonly #areaHitClipPrefix: string;
  readonly #options: RendererOptions;

  constructor(svg: SVGSVGElement, options: RendererOptions) {
    this.#root = d3.select(svg);
    this.#defs = this.#root.append("defs");
    this.#areas = this.#root.append("g").attr("class", "entity-layer entity-layer--areas");
    this.#lines = this.#root.append("g").attr("class", "entity-layer entity-layer--lines");
    this.#hitAreas = this.#root.append("g").attr("class", "entity-layer entity-layer--hits");
    this.#nodes = this.#root.append("g").attr("class", "entity-layer entity-layer--nodes");
    this.#midpoints = this.#root.append("g").attr("class", "entity-layer entity-layer--midpoints");
    this.#preview = this.#root.append("g").attr("class", "entity-layer entity-layer--preview");
    this.#draft = this.#root.append("g").attr("class", "entity-layer entity-layer--draft");
    this.#areaHitClipPrefix = `entity-area-hit-clip-${crypto.randomUUID()}`;
    this.#options = options;
  }

  render(state: RenderState) {
    const { graph, selection, drawing, transientNode, transform } = state;
    const areas = graph.ways().filter((way) => way.geometryKind === "area");
    const lines = graph.ways().filter((way) => way.geometryKind === "line");
    const selectedKey = selection ? entityKey(selection) : null;

    this.#areas
      .selectAll<SVGPathElement, WayEntity>("path.entity-area")
      .data(areas, (way) => way.id)
      .join("path")
      .attr("class", (way) => `entity-area${selectedKey === entityKey(way) ? " is-selected" : ""}`)
      .attr("d", (way) => pathForWay(graph, way, transform, transientNode));

    this.#lines
      .selectAll<SVGPathElement, WayEntity>("path.entity-line")
      .data(lines, (way) => way.id)
      .join("path")
      .attr("class", (way) => `entity-line${selectedKey === entityKey(way) ? " is-selected" : ""}`)
      .attr("d", (way) => pathForWay(graph, way, transform, transientNode));

    const areaHitClips = this.#defs
      .selectAll<SVGClipPathElement, WayEntity>("clipPath.entity-area-hit-clip")
      .data(areas, (way) => way.id)
      .join("clipPath")
      .attr("class", "entity-area-hit-clip")
      .attr("clipPathUnits", "userSpaceOnUse")
      .attr("id", (way) => this.#areaHitClipId(way));

    areaHitClips
      .selectAll<SVGPathElement, WayEntity>("path")
      .data((way) => [way])
      .join("path")
      .attr("d", (way) => pathForWay(graph, way, transform, transientNode));

    this.#hitAreas
      .selectAll<SVGPathElement, WayEntity>("path.entity-hit")
      .data([...areas, ...lines], (way) => way.id)
      .join("path")
      .attr(
        "class",
        (way) =>
          `entity-hit entity-hit--${way.geometryKind}${selectedKey === entityKey(way) ? " is-selected" : ""}`,
      )
      .attr("data-interactive", "true")
      .attr("d", (way) => pathForWay(graph, way, transform, transientNode))
      .attr("clip-path", (way) =>
        way.geometryKind === "area" ? `url(#${this.#areaHitClipId(way)})` : null,
      )
      .on("pointerdown", (event: PointerEvent, way) =>
        this.#options.onEntityPointerDown(event, { type: "way", id: way.id }),
      )
      .on("contextmenu", (event: MouseEvent, way) =>
        this.#options.onEntityContextMenu(event, { type: "way", id: way.id }),
      )
      .on("click", (event: MouseEvent) => event.stopPropagation());

    this.#nodes
      .selectAll<SVGCircleElement, ReturnType<Graph["nodes"]>[number]>("circle.entity-node")
      .data(
        visibleNodesForSelection(graph, selection, {
          showLineVertices: drawing?.geometryKind === "line",
        }),
        (node) => node.id,
      )
      .join("circle")
      .attr("class", (node) => {
        const selected = selectedKey === entityKey(node) ? " is-selected" : "";
        const vertex = graph.parentWays(node.id).length > 0 ? " is-vertex" : " is-point";
        return `entity-node${selected}${vertex}`;
      })
      .attr("data-interactive", "true")
      .attr(
        "cx",
        (node) =>
          worldToScreen(
            transform,
            transientNode?.id === node.id ? transientNode.geom : node.geom,
          )[0],
      )
      .attr(
        "cy",
        (node) =>
          worldToScreen(
            transform,
            transientNode?.id === node.id ? transientNode.geom : node.geom,
          )[1],
      )
      .attr("r", (node) => (selectedKey === entityKey(node) ? 7 : 5))
      .on("pointerdown", (event: PointerEvent, node) =>
        this.#options.onEntityPointerDown(event, { type: "node", id: node.id }),
      )
      .on("contextmenu", (event: MouseEvent, node) =>
        this.#options.onEntityContextMenu(event, { type: "node", id: node.id }),
      )
      .on("click", (event: MouseEvent) => event.stopPropagation());

    const selectedWay = selection?.type === "way" ? graph.way(selection.id) : undefined;
    const midpointData = selectedWay
      ? selectedWay.nodeIds.slice(1).flatMap((nodeId, edgeIndex) => {
          const previousNode = graph.node(selectedWay.nodeIds[edgeIndex]!);
          const nextNode = graph.node(nodeId);
          if (!previousNode || !nextNode) return [];
          return [
            {
              key: `${selectedWay.id}-${edgeIndex + 1}`,
              wayId: selectedWay.id,
              insertionIndex: edgeIndex + 1,
              point: {
                x: (previousNode.geom.x + nextNode.geom.x) / 2,
                y: (previousNode.geom.y + nextNode.geom.y) / 2,
                z: (previousNode.geom.z + nextNode.geom.z) / 2,
              },
            },
          ];
        })
      : [];

    this.#midpoints
      .selectAll<SVGCircleElement, (typeof midpointData)[number]>("circle.entity-midpoint")
      .data(midpointData, (midpoint) => midpoint.key)
      .join("circle")
      .attr("class", "entity-midpoint")
      .attr("data-interactive", "true")
      .attr("cx", (midpoint) => worldToScreen(transform, midpoint.point)[0])
      .attr("cy", (midpoint) => worldToScreen(transform, midpoint.point)[1])
      .attr("r", 4)
      .on("pointerdown", (event: PointerEvent, midpoint) =>
        this.#options.onMidpointPointerDown(
          event,
          midpoint.wayId,
          midpoint.insertionIndex,
          midpoint.point,
        ),
      )
      .on("click", (event: MouseEvent) => event.stopPropagation());

    const previewEntity = state.preview?.graph.entity(state.preview.ref);
    const previewWay = previewEntity?.type === "way" ? previewEntity : null;
    const previewNode = previewEntity?.type === "node" ? previewEntity : null;

    this.#preview
      .selectAll<SVGPathElement, WayEntity>("path.entity-preview--way")
      .data(previewWay ? [previewWay] : [], (way) => entityKey(way))
      .join("path")
      .attr("class", "entity-preview entity-preview--way is-deleted")
      .classed("entity-preview--line", (way) => way.geometryKind === "line")
      .attr("d", (way) => pathForWay(state.preview!.graph, way, transform, null));

    this.#preview
      .selectAll<SVGCircleElement, NodeEntity>("circle.entity-preview--node")
      .data(previewNode ? [previewNode] : [], (node) => entityKey(node))
      .join("circle")
      .attr("class", "entity-preview entity-preview--node is-deleted")
      .attr("cx", (node) => worldToScreen(transform, node.geom)[0])
const POINTER_END_RELEASE_DELAY_MS = 50;

export class CanvasClickSuppression {
  #active = false;
  #timeout: ReturnType<typeof setTimeout> | null = null;

  arm() {
    this.#clearTimeout();
    this.#active = true;
  }

  consume() {
    if (!this.#active) return false;
    this.clear();
    return true;
  }

  releaseAfterPointerEnd(delayMs = POINTER_END_RELEASE_DELAY_MS) {
    if (!this.#active) return;
    this.#clearTimeout();
    this.#timeout = setTimeout(() => {
      this.#timeout = null;
      this.#active = false;
    }, delayMs);
  }

  clear() {
    this.#clearTimeout();
    this.#active = false;
  }

  #clearTimeout() {
    if (this.#timeout === null) return;
    clearTimeout(this.#timeout);
    this.#timeout = null;
  }
}

import { Graph } from "../graph";
import {
  deleteEntity,
  joinedLineNodeIds,
  joinWays,
  splitLineNodeIds,
  splitWayAtNode,
} from "./actions";
import type { GraphAction } from "./history";
import type { EntityRef } from "./types";

export type OperationId = "delete" | "join" | "split";

export type Operation = {
  readonly id: OperationId;
  readonly label: string;
  readonly available: boolean;
  readonly disabledReason: string | null;
  readonly execute: () => void;
};

export type OperationDefinition = Omit<Operation, "execute"> & {
  readonly annotation: string;
  readonly action: GraphAction | null;
  readonly selection: EntityRef | null;
};

export const getOperation = (
  id: OperationId,
  graph: Graph,
  selection: EntityRef | null,
  target: EntityRef | null = null,
  nextLocalWayId = -1,
): OperationDefinition => {
  if (id === "delete") {
    const deleteTarget = target ?? selection;
    const available = deleteTarget !== null && graph.has(deleteTarget);
    return {
      id,
      label: "Delete",
      available,
      disabledReason: available ? null : "Select a feature to delete it.",
      annotation: "Delete feature",
      action: available && deleteTarget ? deleteEntity(deleteTarget) : null,
      selection: null,
    };
  }

  if (id === "join") {
    const selectedWay = selection?.type === "way" ? graph.way(selection.id) : undefined;
    const targetWay = target?.type === "way" ? graph.way(target.id) : undefined;
    const selectedLine = selectedWay?.geometryKind === "line" ? selectedWay : null;
    const targetLine = targetWay?.geometryKind === "line" ? targetWay : null;
    const joinedNodeIds =
      selectedLine && targetLine ? joinedLineNodeIds(selectedLine, targetLine) : null;
    const available = joinedNodeIds !== null;

    let disabledReason: string | null = null;
    if (!selection || !selectedWay) disabledReason = "Select a line to join from.";
    else if (selectedWay.geometryKind !== "line") disabledReason = "Only lines can be joined.";
    else if (!target || !targetWay) disabledReason = "Right-click a line to join it.";
    else if (selection.type === target.type && selection.id === target.id) {
      disabledReason = "Choose another line to join.";
    } else if (targetWay.geometryKind !== "line") disabledReason = "Only lines can be joined.";
    else if (!available) disabledReason = "Lines must share exactly one endpoint.";

    return {
      id,
      label: "Join with selected",
      available,
      disabledReason,
      annotation: "Join lines",
      action:
        available && selectedLine && targetLine ? joinWays(selectedLine.id, targetLine.id) : null,
      selection: selectedLine ? { type: "way", id: selectedLine.id } : null,
    };
  }

  if (id === "split") {
    const selectedWay = selection?.type === "way" ? graph.way(selection.id) : undefined;
    const targetNode = target?.type === "node" ? graph.node(target.id) : undefined;
    const selectedLine = selectedWay?.geometryKind === "line" ? selectedWay : null;
    const splitNodeIds =
      selectedLine && targetNode ? splitLineNodeIds(selectedLine, targetNode.id) : null;
    const localWayIdAvailable = !graph.has({ type: "way", id: nextLocalWayId });
    const available = splitNodeIds !== null && localWayIdAvailable;

    let disabledReason: string | null = null;
    if (!selection || !selectedWay) disabledReason = "Select a line to split.";
    else if (selectedWay.geometryKind !== "line") disabledReason = "Only lines can be split.";
    else if (!target || !targetNode) {
      disabledReason = "Right-click a vertex to split the selected line.";
    } else if (!selectedWay.nodeIds.includes(targetNode.id)) {
      disabledReason = "The vertex must belong to the selected line.";
    } else if (
      selectedWay.nodeIds[0] === targetNode.id ||
      selectedWay.nodeIds.at(-1) === targetNode.id
    ) {
      disabledReason = "Endpoints cannot split a line.";
    } else if (!splitNodeIds) {
      disabledReason = "Choose a vertex that occurs once in the line.";
    } else if (!localWayIdAvailable) {
      disabledReason = "No local Way ID is available.";
    }

    return {
      id,
      label: "Split way",
      available,
      disabledReason,
      annotation: "Split way",
      action:
        available && selectedLine && targetNode
          ? splitWayAtNode(selectedLine.id, targetNode.id, nextLocalWayId)
          : null,
      selection: selectedLine ? { type: "way", id: selectedLine.id } : null,
    };
  }

  return id;
};
import type { Graph } from "../graph";
import type { EditorApiService } from "./api-client";
import { diffResultToRemaps, type ChangesetUploadPayload } from "./changeset";
import { viewportToEntities } from "./types";

export const loadViewportEntities = (
  api: EditorApiService,
  bbox: readonly [number, number, number, number],
) => api.loadViewport(bbox).then(viewportToEntities);

export const saveGraph = (
  api: EditorApiService,
  current: Graph,
  payload: ChangesetUploadPayload,
  comment: string | null,
) =>
  api.save(payload, comment).then((result) => {
    const remaps = diffResultToRemaps(result);
    return {
      graph: current.remapIds(remaps),
      remaps,
    };
  });

import type { components } from "@catlas/api-client";

export type EntityType = "node" | "way";
export type GeometryType = "point" | "line" | "area";
export type EditorMode = "browse" | "add-point" | "draw-line" | "draw-area";
export type SnapPolicy = "integer" | "half" | "free";

export type EntityRef = {
  readonly type: EntityType;
  readonly id: number;
};

export type Point3D = {
  readonly x: number;
  readonly y: number;
  readonly z: number;
};

export type EditorContextMenu = {
  readonly target: EntityRef | null;
  readonly targetEntity: EditorEntity | null;
  readonly world: Point3D;
  readonly x: number;
  readonly y: number;
};

export type NodeEntity = {
  readonly type: "node";
  readonly id: number;
  readonly version: number;
  readonly tags: Readonly<Record<string, string>>;
  readonly geom: Point3D;
};

export type WayEntity = {
  readonly type: "way";
  readonly id: number;
  readonly version: number;
  readonly tags: Readonly<Record<string, string>>;
  readonly geometryKind: "line" | "area";
  readonly nodeIds: readonly number[];
};

export type EditorEntity = NodeEntity | WayEntity;

export type DraftVertex = {
  readonly nodeId: number | null;
  readonly point: Point3D;
};

export type DrawingState = {
  readonly geometryKind: "line" | "area";
  readonly vertices: readonly DraftVertex[];
  readonly pointer: Point3D | null;
};

export type ValidationIssue = {
  readonly id: string;
  readonly severity: "error" | "warning";
  readonly message: string;
  readonly entity: EntityRef | null;
};

export type EditorSaveState =
  | { readonly status: "idle" }
  | { readonly status: "saving" }
  | { readonly status: "saved"; readonly message: string }
  | { readonly status: "error"; readonly message: string };

export type EditorAuthState =
  | { readonly status: "anonymous" }
  | { readonly status: "checking" }
  | { readonly status: "authenticating" }
  | {
      readonly status: "authenticated";
      readonly user: { readonly id: number; readonly userId: string; readonly username: string };
    }
  | { readonly status: "error"; readonly message: string };

export type EditorAuthConfig = {
  readonly oidcEnabled: boolean;
  readonly developerAuthEnabled: boolean;
};

export type EditorSnapshot = {
  readonly mode: EditorMode;
  readonly activeFeatureId: string | null;
  readonly cursor: Point3D | null;
  readonly selection: EntityRef | null;
  readonly selectedEntity: EditorEntity | null;
  readonly changePreview: EntityRef | null;
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  readonly dirty: boolean;
  readonly loading: boolean;
  readonly loadError: string | null;
  readonly drawing: DrawingState | null;
  readonly contextMenu: EditorContextMenu | null;
  readonly issues: readonly ValidationIssue[];
  readonly save: EditorSaveState;
  readonly auth: EditorAuthState;
  readonly authConfig: EditorAuthConfig;
};

export type ViewportEntities = {
  readonly entities: readonly EditorEntity[];
  readonly loadedEntityKeys: ReadonlySet<string>;
};

export const entityKey = ({ type, id }: EntityRef) => `${type[0]}${id}`;

export const entityRef = (entity: EditorEntity): EntityRef => ({
  type: entity.type,
  id: entity.id,
});

export const sameEntityRef = (left: EntityRef | null, right: EntityRef | null) =>
  left?.type === right?.type && left?.id === right?.id;

const toNodeEntity = (node: components["schemas"]["ViewportNode"]): NodeEntity => ({
  type: "node",
  id: node.id,
  version: node.version,
  tags: { ...node.tags },
  geom: { x: node.geom.x, y: node.geom.y, z: node.geom.z },
});

const toWayEntity = (
  way: components["schemas"]["ViewportWay"],
  wayNodes: readonly components["schemas"]["ViewportWayNode"][],
): WayEntity => ({
  type: "way",
  id: way.id,
  version: way.version,
  tags: { ...way.tags },
  geometryKind: way.geometryKind,
  nodeIds: wayNodes
    .filter((wayNode) => wayNode.wayId === way.id)
    .toSorted((left, right) => left.seq - right.seq)
    .map((wayNode) => wayNode.nodeId),
});

export const viewportToEntities = (
  snapshot: components["schemas"]["Viewport"],
): ViewportEntities => {
  const nodes = snapshot.nodes.map(toNodeEntity);
  const ways = snapshot.ways.map((way) => toWayEntity(way, snapshot.wayNodes));
  const entities: EditorEntity[] = [...nodes, ...ways];

  return {
    entities,
    loadedEntityKeys: new Set(entities.map((entity) => entityKey(entity))),
  };
};

export const cloneTags = (tags: Readonly<Record<string, string>>) => ({ ...tags });

export const geometryTypeForEntity = (entity: EditorEntity): GeometryType =>
  entity.type === "node" ? "point" : entity.geometryKind;
