import type * as d3 from "d3";
import { getElementSize, syncCanvas, TILE_WORLD_SIZE } from "./util";

const DEFAULT_TILE_URL = "http://viewer.catlas.localhost:1355/tiles/{x}.{y}.gif";

export class TileCanvasLayer {
  readonly #canvas: HTMLCanvasElement;
  readonly #context: CanvasRenderingContext2D;
  readonly #imageCache = new Map<string, HTMLImageElement>();
  readonly #root: HTMLDivElement;
  readonly #tileUrl: string;
  #animationFrameId: number | null = null;
  #pendingTransform: d3.ZoomTransform | null = null;

  constructor(root: HTMLDivElement, tileUrl = DEFAULT_TILE_URL) {
    const canvas = document.createElement("canvas");
    const context = canvas.getContext("2d");
    if (!context) throw new Error("Canvas 2D context is not available.");

    root.append(canvas);
    this.#canvas = canvas;
    this.#context = context;
    this.#root = root;
    this.#tileUrl = tileUrl;
    this.resize();
  }

  resize() {
    syncCanvas(this.#canvas, this.#context, getElementSize(this.#root));
  }

  setTransform(transform: d3.ZoomTransform) {
    this.#pendingTransform = transform;
    this.#scheduleRender();
  }

  #scheduleRender() {
    if (this.#animationFrameId !== null) return;
    this.#animationFrameId = requestAnimationFrame(() => {
      this.#animationFrameId = null;
      if (this.#pendingTransform) this.#render(this.#pendingTransform);
    });
  }

  #render(transform: d3.ZoomTransform) {
    const size = getElementSize(this.#root);
    syncCanvas(this.#canvas, this.#context, size);
    this.#context.clearRect(0, 0, size.width, size.height);

    const [minSceneX, minSceneZ] = transform.invert([0, 0]);
    const [maxSceneX, maxSceneZ] = transform.invert([size.width, size.height]);
    const minTileX = Math.floor(minSceneX / TILE_WORLD_SIZE);
    const maxTileX = Math.ceil(maxSceneX / TILE_WORLD_SIZE);
    const minTileY = Math.floor(minSceneZ / TILE_WORLD_SIZE);
    const maxTileY = Math.ceil(maxSceneZ / TILE_WORLD_SIZE);

    for (let tileY = minTileY; tileY < maxTileY; tileY += 1) {
      for (let tileX = minTileX; tileX < maxTileX; tileX += 1) {
        const left = transform.applyX(tileX * TILE_WORLD_SIZE);
        const top = transform.applyY(tileY * TILE_WORLD_SIZE);
        const right = transform.applyX((tileX + 1) * TILE_WORLD_SIZE);
        const bottom = transform.applyY((tileY + 1) * TILE_WORLD_SIZE);
        const image = this.#loadTileImage(tileX, tileY);

        if (image.complete && image.naturalWidth > 0) {
          this.#context.drawImage(
            image,
            Math.floor(left),
            Math.floor(top),
            Math.ceil(right) - Math.floor(left),
            Math.ceil(bottom) - Math.floor(top),
          );
        }
      }
    }
  }

  #loadTileImage(x: number, y: number) {
    const key = `${x}.${y}`;
    const cached = this.#imageCache.get(key);
    if (cached) return cached;

    const image = new Image();
    image.decoding = "async";
    image.onload = () => this.#scheduleRender();
    image.src = this.#tileUrl.replace("{x}", String(x)).replace("{y}", String(y));
    this.#imageCache.set(key, image);
    return image;
  }

  destroy() {
    if (this.#animationFrameId !== null) cancelAnimationFrame(this.#animationFrameId);
    for (const image of this.#imageCache.values()) image.onload = null;
    this.#imageCache.clear();
    this.#canvas.remove();
  }
}
import createClient from "openapi-fetch";
import type { components, paths } from "@catlas/api-client";
import { json, noContent } from "../api-response";
import type { ChangesetUploadDiffResult, ChangesetUploadPayload } from "./changeset";

type SessionInfo = { readonly user: components["schemas"]["User"] | null };
type AuthConfig = components["schemas"]["AuthConfigInfo"];
type Changeset = components["schemas"]["Changeset"];

export type ChangesetListPage = {
  readonly changesets: readonly Changeset[];
  readonly nextBeforeId: number | null;
};

export type EditorApiService = {
  readonly getSession: () => Promise<SessionInfo>;
  readonly getAuthConfig: () => Promise<AuthConfig>;
  readonly createSession: (userId: string) => Promise<SessionInfo>;
  readonly deleteSession: () => Promise<void>;
  readonly loadViewport: (
    bbox: readonly [number, number, number, number],
  ) => Promise<components["schemas"]["Viewport"]>;
  readonly listChangesets: (input: {
    readonly beforeId?: number | undefined;
    readonly limit: number;
  }) => Promise<ChangesetListPage>;
  readonly save: (
    payload: ChangesetUploadPayload,
    comment: string | null,
  ) => Promise<ChangesetUploadDiffResult>;
};

export const createEditorApi = (baseUrl: string, worldSlug: string): EditorApiService => {
  const client = createClient<paths>({
    baseUrl: `${baseUrl.replace(/\/$/, "")}/api`,
    credentials: "include",
  });

  const save: EditorApiService["save"] = async (payload, comment) => {
    const changesetResult = await client.POST("/worlds/{worldSlug}/changesets", {
      params: { path: { worldSlug } },
      body: { comment: comment ?? undefined },
    });
    const changeset = await json<Changeset>(changesetResult);
    const changesetId = changeset.id;

    try {
      const uploadResult = await client.POST("/worlds/{worldSlug}/changesets/{id}/upload", {
        params: { path: { worldSlug, id: changesetId } },
        body: payload,
      });
      const diff = await json<ChangesetUploadDiffResult>(uploadResult);
      await json<Changeset>(
        await client.POST("/worlds/{worldSlug}/changesets/{id}/publish", {
          params: { path: { worldSlug, id: changesetId } },
        }),
      );
      return diff;
    } catch (error) {
      try {
        await noContent(
          await client.POST("/worlds/{worldSlug}/changesets/{id}/abandon", {
            params: { path: { worldSlug, id: changesetId } },
          }),
        );
      } catch {
        // Abandon is best effort; preserve the original operation failure.
      }
      throw error;
    }
  };

  return {
    getSession: async () => {
      const session = await json<components["schemas"]["SessionInfo"]>(
        await client.GET("/auth/session"),
      );
      return { user: session.user ?? null };
    },
    getAuthConfig: async () =>
      json<components["schemas"]["AuthConfigInfo"]>(await client.GET("/auth/config")),
    createSession: async (userId) => {
      const session = await json<components["schemas"]["SessionInfo"]>(
        await client.POST("/auth/session", { body: { userId } }),
      );
      return { user: session.user ?? null };
    },
    deleteSession: async () => noContent(await client.DELETE("/auth/session")),
    loadViewport: async (bbox) =>
      json<components["schemas"]["Viewport"]>(
        await client.GET("/worlds/{worldSlug}/viewport", {
          params: {
            path: { worldSlug },
            query: { bbox: bbox.join(","), includeRelations: false },
          },
        }),
      ),
    listChangesets: async ({ beforeId, limit }) => {
      const changesets = await json<readonly Changeset[]>(
        await client.GET("/worlds/{worldSlug}/changesets", {
          params: { path: { worldSlug } },
        }),
      );
      const filtered = changesets.filter(
        (changeset) => beforeId === undefined || changeset.id < beforeId,
      );
      const page = filtered.slice(0, limit);
      return {
        changesets: page,
        nextBeforeId: filtered.length > limit ? (page.at(-1)?.id ?? null) : null,
      };
    },
    save,
  };
};
import { entityEqual, Graph } from "../graph";
import type { components } from "@catlas/api-client";
import { entityKey, type EditorEntity, type NodeEntity, type WayEntity } from "./types";

export type ChangesetUploadPayload = components["schemas"]["ChangesetUploadRequest"];

export type ChangesetUploadDiffResult = components["schemas"]["ChangesetUploadDiffResult"];

export type GraphDifference = {
  readonly created: readonly EditorEntity[];
  readonly modified: readonly EditorEntity[];
  readonly deleted: readonly EditorEntity[];
};

export type ChangesetReviewValue = string | number | null | readonly number[];

export type ChangesetReviewField = {
  readonly key: string;
  readonly label: string;
  readonly before: ChangesetReviewValue;
  readonly after: ChangesetReviewValue;
};

export type ChangesetReviewEntry = {
  readonly key: string;
  readonly kind: "create" | "modify" | "delete";
  readonly ref: { readonly type: "node" | "way"; readonly id: number };
  readonly label: string | null;
  readonly geometry: "point" | "line" | "area";
  readonly expectedVersion: number | null;
  readonly fields: readonly ChangesetReviewField[];
};

export type ChangesetReview = {
  readonly entries: readonly ChangesetReviewEntry[];
  readonly counts: {
    readonly created: number;
    readonly modified: number;
    readonly deleted: number;
    readonly total: number;
  };
  readonly payload: ChangesetUploadPayload;
};

export const difference = (base: Graph, current: Graph): GraphDifference => {
  const created = current.entities().filter((entity) => !base.has(entity));
  const modified = current.entities().filter((entity) => {
    const baseEntity = base.entity(entity);
    return baseEntity !== undefined && !entityEqual(baseEntity, entity);
  });
  const deleted = base.entities().filter((entity) => !current.has(entity));
  return { created, modified, deleted };
};

const nodeCreate = (node: NodeEntity) => ({
  id: node.id,
  geom: node.geom,
  tags: { ...node.tags },
});

const nodeModify = (node: NodeEntity) => ({
  ...nodeCreate(node),
  expectedVersion: node.version,
});

const wayCreate = (way: WayEntity) => ({
  id: way.id,
  geometryKind: way.geometryKind,
  nodeRefs: [...way.nodeIds],
  tags: { ...way.tags },
});

const wayModify = (way: WayEntity) => ({
  ...wayCreate(way),
  expectedVersion: way.version,
});

export const toChangesetUpload = (base: Graph, current: Graph): ChangesetUploadPayload => {
  const diff = difference(base, current);
  const createdNodes = diff.created.filter(
    (entity): entity is NodeEntity => entity.type === "node",
  );
  const createdWays = diff.created.filter((entity): entity is WayEntity => entity.type === "way");
  const modifiedNodes = diff.modified.filter(
    (entity): entity is NodeEntity => entity.type === "node",
  );
  const modifiedWays = diff.modified.filter((entity): entity is WayEntity => entity.type === "way");
  const deletedNodes = diff.deleted.filter(
    (entity): entity is NodeEntity => entity.type === "node",
  );
  const deletedWays = diff.deleted.filter((entity): entity is WayEntity => entity.type === "way");

  return {
    create: {
      nodes: createdNodes.map(nodeCreate),
      ways: createdWays.map(wayCreate),
      relations: [],
    },
    modify: {
      nodes: modifiedNodes.map(nodeModify),
      ways: modifiedWays.map(wayModify),
      relations: [],
    },
    delete: {
      nodes: deletedNodes.map((node) => ({ id: node.id, expectedVersion: node.version })),
      ways: deletedWays.map((way) => ({ id: way.id, expectedVersion: way.version })),
      relations: [],
    },
  };
};

const valuesEqual = (left: ChangesetReviewValue, right: ChangesetReviewValue) => {
  if (Array.isArray(left) && Array.isArray(right)) {
    return left.length === right.length && left.every((value, index) => value === right[index]);
  }
  return left === right;
};

const fieldChanges = (
  kind: ChangesetReviewEntry["kind"],
  before: EditorEntity | null,
  after: EditorEntity | null,
) => {
  const fields: ChangesetReviewField[] = [];
  const include = (
    key: string,
    label: string,
    beforeValue: ChangesetReviewValue,
    afterValue: ChangesetReviewValue,
  ) => {
    if (kind === "modify" && valuesEqual(beforeValue, afterValue)) return;
    fields.push({ key, label, before: beforeValue, after: afterValue });
  };

  if (before?.type === "node" || after?.type === "node") {
    const beforeNode = before?.type === "node" ? before : null;
    const afterNode = after?.type === "node" ? after : null;
    include("geom.x", "X", beforeNode?.geom.x ?? null, afterNode?.geom.x ?? null);
    include("geom.y", "Y", beforeNode?.geom.y ?? null, afterNode?.geom.y ?? null);
    include("geom.z", "Z", beforeNode?.geom.z ?? null, afterNode?.geom.z ?? null);
  }

  if (before?.type === "way" || after?.type === "way") {
    const beforeWay = before?.type === "way" ? before : null;
    const afterWay = after?.type === "way" ? after : null;
    include(
      "geometryKind",
      "Geometry",
      beforeWay?.geometryKind ?? null,
      afterWay?.geometryKind ?? null,
    );
    include("nodeRefs", "Node refs", beforeWay?.nodeIds ?? null, afterWay?.nodeIds ?? null);
  }

  const tagKeys = new Set([...Object.keys(before?.tags ?? {}), ...Object.keys(after?.tags ?? {})]);
  for (const key of [...tagKeys].toSorted()) {
    include(`tags.${key}`, `Tag: ${key}`, before?.tags[key] ?? null, after?.tags[key] ?? null);
  }

  return fields;
};

const reviewEntry = (
  kind: ChangesetReviewEntry["kind"],
  before: EditorEntity | null,
  after: EditorEntity | null,
): ChangesetReviewEntry => {
  const entity = after ?? before;
  if (!entity) throw new Error("A changeset review entry requires an entity");

  return {
    key: entityKey(entity),
    kind,
    ref: { type: entity.type, id: entity.id },
    label: entity.tags.name ?? null,
    geometry: entity.type === "node" ? "point" : entity.geometryKind,
    expectedVersion: kind === "create" ? null : entity.version,
    fields: fieldChanges(kind, before, after),
  };
};

export const buildChangesetReview = (base: Graph, current: Graph): ChangesetReview => {
  const diff = difference(base, current);
  const created = diff.created.map((entity) => reviewEntry("create", null, entity));
  const modified = diff.modified.map((entity) =>
    reviewEntry("modify", base.entity(entity) ?? null, entity),
  );
  const deleted = diff.deleted.map((entity) => reviewEntry("delete", entity, null));

  return {
    entries: [...created, ...modified, ...deleted],
    counts: {
      created: created.length,
      modified: modified.length,
      deleted: deleted.length,
      total: created.length + modified.length + deleted.length,
    },
    payload: toChangesetUpload(base, current),
  };
};

export const diffResultToRemaps = (result: ChangesetUploadDiffResult) =>
  new Map<string, { readonly id: number; readonly version: number }>([
    ...result.nodes.map(
      (entry) => [`n${entry.oldId}`, { id: entry.newId, version: entry.newVersion }] as const,
    ),
    ...result.ways.map(
      (entry) => [`w${entry.oldId}`, { id: entry.newId, version: entry.newVersion }] as const,
    ),
  ]);

export const countChanges = (base: Graph, current: Graph) => {
  const diff = difference(base, current);
  return diff.created.length + diff.modified.length + diff.deleted.length;
};

export const changedEntityKeys = (base: Graph, current: Graph) => {
  const diff = difference(base, current);
  return new Set([...diff.created, ...diff.modified, ...diff.deleted].map(entityKey));
};

import type { NodeEntity, WayEntity } from "../src/lib/editor/types";

export const node = (id: number, x = id, z = id, version = id < 0 ? 0 : 1): NodeEntity => ({
  type: "node",
  id,
  version,
  tags: {},
  geom: { x, y: 0, z },
});

export const line = (
  id: number,
  nodeIds: readonly number[],
  version = id < 0 ? 0 : 1,
): WayEntity => ({
  type: "way",
  id,
  version,
  tags: {},
  geometryKind: "line",
  nodeIds,
});

export const area = (
  id: number,
  nodeIds: readonly number[],
  version = id < 0 ? 0 : 1,
): WayEntity => ({
  type: "way",
  id,
  version,
  tags: {},
  geometryKind: "area",
  nodeIds,
});
