import Projection from "ol/proj/Projection.js";
import type { Coordinate } from "ol/coordinate.js";
import type { Extent } from "ol/extent.js";
import type { BBox, Point } from "@catlas/api-client";

export const CATLAS_PROJECTION_CODE = "CATLAS";
export const CATLAS_NATIVE_ZOOM = 3;
export const CATLAS_MIN_ZOOM = -1;
export const CATLAS_INITIAL_ZOOM = 0;
export const CATLAS_INITIAL_RESOLUTION = 2 ** (CATLAS_NATIVE_ZOOM - CATLAS_INITIAL_ZOOM);

export const catlasProjection = new Projection({
  code: CATLAS_PROJECTION_CODE,
  units: "pixels",
});

export type MapCoordinate = [number, number];

const reflect = (value: number): number => (value === 0 ? 0 : -value);

export const worldToMapCoordinate = (point: Pick<Point, "x" | "z">): MapCoordinate => [
  reflect(point.x),
  reflect(point.z),
];

export const mapToWorldCoordinate = ([x, y]: Coordinate): { x: number; z: number } => ({
  x: reflect(x),
  z: reflect(y),
});

export const resolutionForCatlasZoom = (zoom: number): number => 2 ** (CATLAS_NATIVE_ZOOM - zoom);

export const catlasZoomForResolution = (resolution: number): number =>
  CATLAS_NATIVE_ZOOM - Math.log2(resolution);

export const mapExtentToWorldBbox = (extent: Extent): BBox => [
  -extent[2],
  -extent[3],
  -extent[0],
  -extent[1],
];

export const worldBboxToMapExtent = (bbox: BBox): Extent => [
  -bbox[2],
  -bbox[3],
  -bbox[0],
  -bbox[1],
];
import { describe, expect, test } from "vite-plus/test";
import {
  CATLAS_MIN_ZOOM,
  catlasProjection,
  catlasZoomForResolution,
  resolutionForCatlasZoom,
  mapExtentToWorldBbox,
  mapToWorldCoordinate,
  worldBboxToMapExtent,
  worldToMapCoordinate,
} from "./projection.ts";
import { CATLAS_TILE_SIZE, catlasTileUrl } from "./tiles.ts";

describe("Catlas OpenLayers coordinate contract", () => {
  test("uses a non-wrapping pixel projection for the map view", () => {
    expect(catlasProjection.getCode()).toBe("CATLAS");
    expect(catlasProjection.getUnits()).toBe("pixels");
  });

  test("maps world x/z into the OpenLayers y-up coordinate system", () => {
    expect(worldToMapCoordinate({ x: 12, z: -7 })).toEqual([-12, 7]);
    expect(mapToWorldCoordinate([-12, 7])).toEqual({ x: 12, z: -7 });
  });

  test("converts view extents and API bboxes with both axes reflected", () => {
    const extent = [-512, -256, 512, 256];
    expect(mapExtentToWorldBbox(extent)).toEqual([-512, -256, 512, 256]);
    expect(worldBboxToMapExtent([-512, -256, 512, 256])).toEqual([-512, -256, 512, 256]);
  });

  test("keeps Catlas native zoom 3 at one map pixel per world unit", () => {
    expect(resolutionForCatlasZoom(3)).toBe(1);
    expect(resolutionForCatlasZoom(0)).toBe(8);
    expect(catlasZoomForResolution(0.25)).toBe(5);
  });

  test("allows one additional wide-area zoom level below the initial view", () => {
    expect(CATLAS_MIN_ZOOM).toBe(-1);
    expect(resolutionForCatlasZoom(CATLAS_MIN_ZOOM)).toBe(16);
  });

  test("builds tile URLs using the signed tile coordinates", () => {
    expect(CATLAS_TILE_SIZE).toBe(512);
    expect(catlasTileUrl("/tiles/{x}.{y}.gif", -2, 4)).toBe("/tiles/-2.4.gif");
  });
});
# Catlas OpenLayers viewer

`@catlas/viewer-ol` is the SolidJS + OpenLayers viewer. It keeps the existing
React + Leaflet viewer in `@catlas/viewer` available while the new viewer is
developed separately.

Run it from the repository root with:

```sh
vp run --filter=@catlas/viewer-ol dev
vp run --filter=@catlas/viewer-ol build
```

The viewer uses Catlas world coordinates (`x`, `z`) as map coordinates
`[-x, -z]`, a 512px tile grid, and the relative `/tiles/{x}.{y}.gif` tile
contract. Feature data is requested from the shared `@catlas/api-client`
viewport service and rendered with OpenLayers `VectorLayer`s.
# Catlas Editor

An iD-style world editor for Catlas game maps. The editor works in the XZ plane,
keeps Y as an inspected property, and synchronizes entities through the Catlas API.
Each map tile covers `512 x 512` world cells. At the initial zoom level, one cell is
rendered as one CSS pixel, matching the native `512 x 512` tile image.

## Architecture

The implementation is split into the same layers that make an interactive map
editor manageable:

1. `Graph` is the immutable entity store for nodes and ways.
2. `History` records annotated graph transitions and provides undo/redo.
3. `Actions` are small graph transformations such as moving a node or changing tags.
4. `Modes` and pointer behaviors decide how input becomes actions.
5. `Operations` expose user commands with availability, disabled reasons, and `execute()`.
6. `Snapping` applies geometry-based coordinate policies while drawing and moving entities.
7. `Validation` reports structural issues before upload.
8. `Renderer` draws areas, lines, nodes, midpoints, and active drawing state with D3/SVG.
9. `Sync` loads viewport entities and uploads changesets through the Catlas API client.
10. React renders the toolbar, inspector, validation state, and save controls around the editor.

## Authentication

Editing is available without a session, but publishing requires a Catlas API session.
When OIDC is configured, the toolbar starts the API's OpenID Connect login and returns to the
current editor route after authentication. The API stores the resulting identity in its
HttpOnly session cookie. A developer sign-in through `POST /auth/session` remains available only
when development auth is enabled. The editor checks the session on startup and immediately
before publishing. Signing out deletes the session when the API is reachable and always clears
the local authentication state.

Relations are deliberately outside the current editing surface. The graph and API
boundaries leave room for them without mixing relation behavior into the first
point/line/area milestone.

## Public Editor API

`CatlasEditor` owns the mutable session and exposes snapshots through
`getSnapshot()` and `subscribe()`. UI commands use methods such as `setMode()`,
`undo()`, `redo()`, and `save()`. Commands that need availability
metadata are obtained with `operation(id)`.

## Development

```sh
vp install
vp dev
vp check
vp test
vp build
```

The default development setup proxies `/api` to the Catlas API and `/tiles` to the
tile service. Editing remains local when either service is unavailable, so a failed
load or publish does not discard the current history.

