        tabIndex={0}
      >
        <ViewportLayers
          locale={props.locale}
          onProjected={setProjected}
          registerViewChange={(handler) => {
            triggerViewChange = handler;
import { createCatlasApi, type CatlasApi, type BBox, type World } from "@catlas/api-client";
