import * as d3 from "d3";
import type { Point3D } from "./types";

export type Size = { readonly height: number; readonly width: number };
export type Extent = [[number, number], [number, number]];

export const TILE_PIXEL_SIZE = 512;
export const TILE_WORLD_SIZE = 512;
const INITIAL_PIXELS_PER_WORLD_UNIT = TILE_PIXEL_SIZE / TILE_WORLD_SIZE;
const FALLBACK_SIZE: Size = { height: 200, width: 200 };

export const createSvgElement = () => document.createElementNS("http://www.w3.org/2000/svg", "svg");

export const getElementSize = (element: HTMLElement): Size => {
  const rect = element.getBoundingClientRect();
  return {
    width: rect.width || window.innerWidth || FALLBACK_SIZE.width,
    height: rect.height || window.innerHeight || FALLBACK_SIZE.height,
  };
};

export const getViewportExtent = ({ height, width }: Size): Extent => [
  [0, 0],
  [width, height],
];

export const getInitialTransform = ({ height, width }: Size) =>
  d3.zoomIdentity.translate(width / 2, height / 2).scale(INITIAL_PIXELS_PER_WORLD_UNIT);

export const getZoomScaleExtent = (): [number, number] => [1 / 16, 32];

export const worldToScreen = (transform: d3.ZoomTransform, point: Pick<Point3D, "x" | "z">) =>
  transform.apply([-point.x, point.z]) as [number, number];

export const screenToWorld = (
  transform: d3.ZoomTransform,
  screen: readonly [number, number],
  y = 0,
): Point3D => {
  const [sceneX, sceneZ] = transform.invert([screen[0], screen[1]]);
  return { x: -sceneX, y, z: sceneZ };
};

export const getViewportBbox = (
  transform: d3.ZoomTransform,
  { width, height }: Size,
): readonly [number, number, number, number] => {
  const topLeft = screenToWorld(transform, [0, 0]);
  const bottomRight = screenToWorld(transform, [width, height]);
  return [
    Math.min(topLeft.x, bottomRight.x),
    Math.min(topLeft.z, bottomRight.z),
    Math.max(topLeft.x, bottomRight.x),
    Math.max(topLeft.z, bottomRight.z),
  ];
};

export const syncCanvas = (
  canvas: HTMLCanvasElement,
  context: CanvasRenderingContext2D,
  size: Size,
) => {
  const pixelRatio = window.devicePixelRatio || 1;
  const width = Math.max(1, Math.round(size.width * pixelRatio));
  const height = Math.max(1, Math.round(size.height * pixelRatio));

  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }

  context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
  context.imageSmoothingEnabled = false;
};
import Projection from "ol/proj/Projection.js";
import type { Coordinate } from "ol/coordinate.js";
import type { Extent } from "ol/extent.js";
import type { BBox, Point } from "@catlas/api-client";

export const CATLAS_PROJECTION_CODE = "CATLAS";
export const CATLAS_NATIVE_ZOOM = 3;
export const CATLAS_MIN_ZOOM = -1;
export const CATLAS_INITIAL_ZOOM = 0;
export const CATLAS_INITIAL_RESOLUTION = 2 ** (CATLAS_NATIVE_ZOOM - CATLAS_INITIAL_ZOOM);

export const catlasProjection = new Projection({
  code: CATLAS_PROJECTION_CODE,
  units: "pixels",
});

export type MapCoordinate = [number, number];

const reflect = (value: number): number => (value === 0 ? 0 : -value);

export const worldToMapCoordinate = (point: Pick<Point, "x" | "z">): MapCoordinate => [
  reflect(point.x),
  reflect(point.z),
];

export const mapToWorldCoordinate = ([x, y]: Coordinate): { x: number; z: number } => ({
  x: reflect(x),
  z: reflect(y),
});

export const resolutionForCatlasZoom = (zoom: number): number => 2 ** (CATLAS_NATIVE_ZOOM - zoom);

export const catlasZoomForResolution = (resolution: number): number =>
  CATLAS_NATIVE_ZOOM - Math.log2(resolution);

export const mapExtentToWorldBbox = (extent: Extent): BBox => [
  -extent[2],
  -extent[3],
  -extent[0],
  -extent[1],
];

export const worldBboxToMapExtent = (bbox: BBox): Extent => [
  -bbox[2],
  -bbox[3],
  -bbox[0],
  -bbox[1],
];
import { CRS as lCrs, extend as lExtend, transformation as lTransformation } from "leaflet";
import { useRef } from "react";
import { Map } from "../leaflet/map.tsx";
import { cn } from "../lib/utils.ts";

export const zoom = 3;

export const CatlasMap = ({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) => {
  const mapOptions = useRef<L.MapOptions>({
    center: [0, 0],
    zoom: 0,
    minZoom: 0,
    preferCanvas: true,
    crs: lExtend({}, lCrs.Simple, {
      transformation: lTransformation(-1 / 2 ** zoom, 0, 1 / 2 ** zoom, 0),
    }),
    zoomControl: false,
    attributionControl: false,
  });

  return (
    <Map className={cn(["h-full", "w-full", className])} initialOptions={mapOptions.current}>
      {children}
    </Map>
  );
};

