const results = await Promise.all([
  tools.exec_command({
    cmd: "PGPASSWORD=REDACTED psql -h 127.0.0.1 -U catlas -d catlas -Atc \"SELECT c.id, c.comment, count(n.id) FILTER (WHERE n.created_changeset_id = c.id) AS created_nodes, count(n.id) FILTER (WHERE n.changeset_id = c.id) AS current_nodes, count(w.id) FILTER (WHERE w.created_changeset_id = c.id) AS created_ways FROM core.changesets c LEFT JOIN core.nodes n ON n.world_id = c.world_id LEFT JOIN core.ways w ON w.world_id = c.world_id WHERE c.world_id = (SELECT id FROM core.worlds WHERE slug = 'sayama') AND c.id BETWEEN 60 AND 70 GROUP BY c.id, c.comment ORDER BY c.id;\"",
    workdir: "/Users/tsutoringo/Documents/workspaces/private/project/catlas/catlas-web",
    yield_time_ms: 10000,
    max_output_tokens: 10000
  }),
  tools.exec_command({
    cmd: "PGPASSWORD=REDACTED psql -h 127.0.0.1 -U catlas -d catlas -Atc \"SELECT n.id, n.version, n.mc_x, n.mc_y, n.mc_z, n.created_changeset_id, n.changeset_id, n.tags::text FROM core.nodes n WHERE n.world_id = (SELECT id FROM core.worlds WHERE slug = 'sayama') AND n.changeset_id IN (68,69,70) ORDER BY n.id LIMIT 120;\"",
    workdir: "/Users/tsutoringo/Documents/workspaces/private/project/catlas/catlas-web",
    yield_time_ms: 10000,
    max_output_tokens: 20000
  }),
  tools.exec_command({
    cmd: "PGPASSWORD=REDACTED psql -h 127.0.0.1 -U catlas -d catlas -Atc \"SELECT node_id, version, changeset_id, snapshot->'geom'->>'x' AS x, snapshot->'geom'->>'z' AS z FROM history.node_versions WHERE changeset_id IN (68,69,70) ORDER BY changeset_id, node_id, version LIMIT 240;\"",
    workdir: "/Users/tsutoringo/Documents/workspaces/private/project/catlas/catlas-web",
    yield_time_ms: 10000,
    max_output_tokens: 24000
  }),
  tools.exec_command({
    cmd: "PGPASSWORD=REDACTED psql -h 127.0.0.1 -U catlas -d catlas -Atc \"SELECT c.id, c.comment, c.world_id, c.created_by_user_id, c.status, c.created_at, c.published_at FROM core.changesets c WHERE c.id IN (68,69,70);\"",
    workdir: "/Users/tsutoringo/Documents/workspaces/private/project/catlas/catlas-web",
    yield_time_ms: 10000,
    max_output_tokens: 10000
  })
]);
for (const r of results) text(r.output);

const r = await tools.exec_command({
  cmd: "curl -sS --max-time 15 \"http://127.0.0.1:3000/api/worlds/sayama/viewport?bbox=-1000000000,-1000000000,1000000000,1000000000&includeRelations=false\" | jq '{totalNodes:(.nodes|length),byCurrentChangeset:([.nodes[]|.changesetId]|sort|group_by(.)|map({changesetId:.[0],count:length})),byCreatedChangeset:([.nodes[]|.createdChangesetId]|sort|group_by(.)|map({changesetId:.[0],count:length})),sample69:([.nodes[]|select(.changesetId==69)|{id,version,geom,tags}][0:10]),sample68:([.nodes[]|select(.createdChangesetId==68)|{id,version,geom,tags}][0:5])}'",
  workdir: "/Users/tsutoringo/Documents/workspaces/private/project/catlas/catlas-web",
  yield_time_ms: 10000,
  max_output_tokens: 18000
});
text(r.output);

