    /// 新規セッションを発行する
    ///
    /// テスト用のセッションを発行する。
    #[oai(path = "/session", method = "post")]
    async fn create_session(
        &self,
        Json(request): Json<CreateSession>,
        session: &Session,
        Data(auth): Data<&AuthState>,
        Data(pool): Data<&DatabasePool>,
    ) -> poem::Result<Json<SessionInfo>> {
        if !auth.developer_auth_enabled() {
            return Err(poem::Error::from_status(poem::http::StatusCode::NOT_FOUND));
        }
        let user_id = request.user_id.as_str();
        if user_id.is_empty()
            || user_id.len() > 128
            || !user_id.bytes().all(|byte| {
                byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_' || byte == b'-'
            })
        {
            return Err(poem::Error::from_status(
                poem::http::StatusCode::BAD_REQUEST,
            ));
        }
        let user_id = user_id.to_owned();
        let user = database::blocking(pool, move |c| provision_user(c, &user_id))
            .await
            .map_err(crate::modules::common::support::db_error)?;
        session.renew();
        session.set("user_id", user.0);
        Ok(Json(SessionInfo {
            user: Nullable(Some(User {
                id: user.0,
                user_id: user.1,
                username: user.2,
            })),
        }))
    }

    #[oai(path = "/session", method = "delete")]
    async fn delete_session(&self, session: &Session) -> poem::Result<NoContent> {
        session.purge();
    config: Config,
    tracer: SdkTracer,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let database_url = config.database_url().to_owned();
    let database =
        tokio::task::spawn_blocking(move || database::connect_and_migrate(database_url)).await??;
    let auth_state = auth::AuthState::from_config(config.auth()).await?;

    let api_service = openapi_service();

    // api_serviceをRouteに移動する前に生成する
    let swagger_ui = api_service.scalar();
    let spec_endpoint = api_service.spec_endpoint();

    let server_session = ServerSession::new(
        CookieConfig::default()
            .http_only(true)
            .secure(config.cookie_secure())
            .same_site(SameSite::Lax),
        MemoryStorage::new(),
    );

    let app = Route::new()
        .nest("/api", api_service)
        .at("/api/openapi.json", spec_endpoint)
        .nest("/docs", swagger_ui)
        .with(OpenTelemetryTracing::new(tracer))
        .with(server_session)
        .data(config.clone())
        .data(database)
        .data(auth_state);

    let address = format!("{}:{}", config.host(), config.port());
    Server::new(TcpListener::bind(address)).run(app).await?;

    Ok(())

