import { tileLayer, type TileLayerOptions } from "leaflet";
import { useLayerLifecycleRef } from "./hooks/useLayerLifeCycle.tsx";

export interface CTileLayerProps extends TileLayerOptions {
  urlTemplate: string;
}

export const CTileLayer = ({ urlTemplate, ...options }: CTileLayerProps): null => {
  useLayerLifecycleRef(() => tileLayer(urlTemplate, options));

  return null;
};
import { cn } from "../lib/utils.ts";
import { LeafletContext } from "./context/map.ts";
import { ParentContext } from "./context/parent.ts";
import { useLeafletMap } from "./hooks/useLeaflet.ts";
import type { ReactNode } from "react";

export const Map = ({
  children,
  initialOptions,
  className,
}: {
  children?: ReactNode;
  initialOptions: L.MapOptions;
  className: string;
}) => {
  const { mapRef, map } = useLeafletMap({ options: initialOptions });

  return (
    <div className={cn(className, "c-map")} ref={mapRef}>
      {map && (
        <ParentContext.Provider value={{ parent: map }}>
          <LeafletContext.Provider value={{ map }}>{children}</LeafletContext.Provider>
        </ParentContext.Provider>
      )}
    </div>
  );
};
import {
  type LatLngExpression,
  type LeafletEventHandlerFnMap,
  polyline,
  type PolylineOptions,
} from "leaflet";
import { useEffect } from "react";
import { useLayerLifecycleRef } from "../hooks/useLayerLifeCycle.tsx";

export interface CPolylineProps extends PolylineOptions {
  eventHandlers?: LeafletEventHandlerFnMap;
  positions: LatLngExpression[] | LatLngExpression[][];
}

export const Polyline = ({ eventHandlers, positions, ...options }: CPolylineProps): null => {
  const polylineRef = useLayerLifecycleRef(() => polyline(positions, options));

  useEffect(() => {
    if (polylineRef.current) {
      polylineRef.current.setLatLngs(positions);
      polylineRef.current.setStyle(options);
    }
  }, [options, positions]);

  useEffect(() => {
    if (!polylineRef.current || !eventHandlers) {
      return;
    }

    polylineRef.current.on(eventHandlers);

    return () => {
      polylineRef.current?.off(eventHandlers);
    };
  }, [eventHandlers]);

  return null;
};
import {
  type LatLngExpression,
  type LeafletEventHandlerFnMap,
  marker,
  type MarkerOptions,
} from "leaflet";
import { useEffect } from "react";
import { useLayerLifecycleRef } from "./hooks/useLayerLifeCycle.tsx";

export interface CMarkerProps extends MarkerOptions {
  eventHandlers?: LeafletEventHandlerFnMap;
  position: LatLngExpression;
}

export const Marker = ({ eventHandlers, position, ...options }: CMarkerProps): null => {
  const markerRef = useLayerLifecycleRef(() => marker(position, options));

  useEffect(() => {
    if (markerRef.current) {
      markerRef.current.setLatLng(position);
    }
  }, [position]);

  useEffect(() => {
    if (!markerRef.current || !eventHandlers) {
      return;
    }

    markerRef.current.on(eventHandlers);

    return () => {
      markerRef.current?.off(eventHandlers);
    };
  }, [eventHandlers]);

  return null;
};

