const ICON_PATHS: Readonly<Record<string, string>> = {
  base: '<path d="M4 10.5 12 4l8 6.5V20h-5v-6H9v6H4z"/>',
  building: '<path d="M4 21V9l8-5 8 5v12M4 21h16M9 21v-5h6v5M8 11h2M14 11h2"/>',
