import * as d3 from "/node_modules/.vite/deps/d3.js?v=193171b6";
export const TILE_PIXEL_SIZE = 512;
export const TILE_WORLD_SIZE = 512;
const INITIAL_PIXELS_PER_WORLD_UNIT = TILE_PIXEL_SIZE / TILE_WORLD_SIZE;
const FALLBACK_SIZE = {
	height: 200,
	width: 200
};
export const createSvgElement = () => document.createElementNS("http://www.w3.org/2000/svg", "svg");
export const getElementSize = (element) => {
	const rect = element.getBoundingClientRect();
	return {
		width: rect.width || window.innerWidth || FALLBACK_SIZE.width,
		height: rect.height || window.innerHeight || FALLBACK_SIZE.height
	};
};
export const getViewportExtent = ({ height, width }) => [[0, 0], [width, height]];
export const getInitialTransform = ({ height, width }) => d3.zoomIdentity.translate(width / 2, height / 2).scale(INITIAL_PIXELS_PER_WORLD_UNIT);
export const getZoomScaleExtent = () => [1 / 16, 32];
export const worldToScreen = (transform, point) => transform.apply([point.x, point.z]);
export const screenToWorld = (transform, screen, y = 0) => {
	const [sceneX, sceneZ] = transform.invert([screen[0], screen[1]]);
	return {
		x: sceneX,
		y,
		z: sceneZ
	};
};
export const getViewportBbox = (transform, { width, height }) => {
	const topLeft = screenToWorld(transform, [0, 0]);
	const bottomRight = screenToWorld(transform, [width, height]);
	return [
		Math.min(topLeft.x, bottomRight.x),
		Math.min(topLeft.z, bottomRight.z),
		Math.max(topLeft.x, bottomRight.x),
		Math.max(topLeft.z, bottomRight.z)
	];
};
export const syncCanvas = (canvas, context, size) => {
	const pixelRatio = window.devicePixelRatio || 1;
	const width = Math.max(1, Math.round(size.width * pixelRatio));
	const height = Math.max(1, Math.round(size.height * pixelRatio));
	if (canvas.width !== width || canvas.height !== height) {
		canvas.width = width;
		canvas.height = height;
	}
	context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
	context.imageSmoothingEnabled = false;
};

