const results = await Promise.all([
  tools.exec_command({
    cmd: "docker exec catlas-postgis psql -U catlas -d catlas -At -F $'\\t' -c \"SELECT w.id, w.changeset_id, w.geometry_kind, jsonb_object_keys(w.tags) FROM core.ways w WHERE w.world_id=(SELECT id FROM core.worlds WHERE slug='sayama') ORDER BY w.id;\"",
    workdir: "/Users/tsutoringo/Documents/workspaces/private/project/catlas/catlas-web",
    yield_time_ms: 10000,
    max_output_tokens: 2000
  }),
  tools.exec_command({
    cmd: "docker exec catlas-postgis psql -U catlas -d catlas -At -F $'\\t' -c \"SELECT w.id, w.changeset_id, w.geometry_kind, w.tags::text, count(wn.node_id) AS node_count, count(DISTINCT wn.node_id) AS distinct_nodes FROM core.ways w LEFT JOIN core.way_nodes wn ON wn.way_id=w.id WHERE w.world_id=(SELECT id FROM core.worlds WHERE slug='sayama') GROUP BY w.id, w.changeset_id, w.geometry_kind, w.tags ORDER BY w.id;\"",
    workdir: "/Users/tsutoringo/Documents/workspaces/private/project/catlas/catlas-web",
    yield_time_ms: 10000,
    max_output_tokens: 12000
  }),
  tools.exec_command({
    cmd: "docker exec catlas-postgis psql -U catlas -d catlas -At -F $'\\t' -c \"SELECT id, comment FROM core.changesets WHERE world_id=(SELECT id FROM core.worlds WHERE slug='sayama') AND id BETWEEN 60 AND 72 ORDER BY id;\"",
    workdir: "/Users/tsutoringo/Documents/workspaces/private/project/catlas/catlas-web",
    yield_time_ms: 10000,
    max_output_tokens: 4000
  })
]);
for (const r of results) text(r.output);

